import React, { useState, useEffect } from 'react';
import './RiverDashboard.css';

// ==========================================
// CONFIGURATION
// ==========================================
const DATA_BASE_URL = '.';
const CSV_FILE = 'forecast_outputs.csv';
const TXT_FILE = 'lime_short_sentences.txt';

const RiverDashboard = () => {
  const [forecastData, setForecastData] = useState([]);
  const [limeDetails, setLimeDetails] = useState([]);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);

  // Helper: Parse CSV
  const parseCSV = (csvText) => {
    const lines = csvText.split('\n').filter(line => line.trim() !== '');
    if (lines.length < 2) return []; 
    const headers = lines[0].split(',').map(h => h.trim());
    const data = [];
    for (let i = 1; i < lines.length; i++) {
        const values = lines[i].split(',');
        if (values.length === headers.length) {
            let rowObject = {};
            for (let j = 0; j < headers.length; j++) {
                rowObject[headers[j]] = values[j].trim();
            }
            data.push(rowObject);
        }
    }
    return data;
  };

  useEffect(() => {
    const fetchData = async () => {
      setIsLoading(true);
      setError(null);
      try {
        // Fetch CSV
        const csvRes = await fetch(`${DATA_BASE_URL}/${CSV_FILE}`);
        if (!csvRes.ok) throw new Error('Failed to fetch forecast data');
        const csvText = await csvRes.text();
        setForecastData(parseCSV(csvText));

        // Fetch LIME Text
        const txtRes = await fetch(`${DATA_BASE_URL}/${TXT_FILE}`);
        if (!txtRes.ok) throw new Error('Failed to fetch analysis data');
        const txtText = await txtRes.text();
        setLimeDetails(txtText.split('\n').filter(line => line.trim() !== ''));

      } catch (err) {
        console.error("Data Load Error:", err);
        setError("Unable to load dashboard data. Please check connection.");
      } finally {
        setIsLoading(false);
      }
    };

    fetchData();
  }, []);

  if (isLoading) return <div className="dashboard-loading">Initializing Dashboard...</div>;
  if (error) return <div className="dashboard-error">{error}</div>;

  const tableHeaders = forecastData.length > 0 ? Object.keys(forecastData[0]) : [];
  
  // Determine Status (Logic can be expanded based on real data)
  // Hardcoded for now based on your previous design
  const currentStatus = "Normal"; 
  const statusClass = currentStatus === "Normal" ? "status-normal" : "status-warning";

  return (
    <div className="dashboard">
      
      {/* HEADER */}
      <header className="dashboard-header">
        <div className="header-content">
          <h1>Periyar River Monitor</h1>
          <p className="last-updated">System Updated: 8/08/24</p>
        </div>
      </header>

      <div className="dashboard-grid">
        
        {/* CARD 1: HERO METRIC (Current Water Level) */}
        <div className="card current-level-card">
          <h2>
            <span>Current Status</span>
          </h2>
          <div className="level-display-container">
              <div className="level-value-box">
                  <span className="value">1.41</span>
                  <span className="unit">meters</span>
              </div>
              
              <div className={`level-status-indicator ${statusClass}`}>
                  <span className="status-dot"></span>
                  {currentStatus} Conditions
              </div>

              <div className="level-date">
                  <span className="label">Measured on:</span> 8/08/24
              </div>
          </div>
        </div>

        {/* CARD 2: FORECAST GRID */}
        <div className="card forecast-section">
            <h2>
              <span>6-Hour Forecast</span>
            </h2>

            {forecastData.length > 0 ? (
            <div className="forecast-grid">
              {forecastData.map((row, rowIndex) => (
                <div key={rowIndex} className="forecast-item-card">
                    {tableHeaders.map((header, colIndex) => (
                    <div key={colIndex} className="forecast-detail">
                        <span className="detail-label">{header.replace(/_/g, " ")}</span>
                        <span className="detail-value">{row[header]}</span>
                    </div>
                    ))}
                </div>
              ))}
            </div>
            ) : (
            <p className="no-data">No forecast data available.</p>
            )}
        </div>

        {/* CARD 3: AI INSIGHTS (LIME) */}
        <div className="card lime-card">
          <h2>
            <span>AI Risk Analysis (LIME)</span>
          </h2>
          {limeDetails.length > 0 ? (
            <ul className="lime-list">
                {limeDetails.map((detail, index) => (
                    <li key={index}>{detail}</li>
                ))}
            </ul>
          ) : (
              <p>No analysis details available.</p>
          )}
        </div>

      </div>

      <footer className="dashboard-footer">
        <p>&copy; 2024 Periyar River Monitoring Authority | Intelligent Water Systems</p>
      </footer>
    </div>
  );
};

export default RiverDashboard;
